// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address token) public {
        vm.assume(token != address(0));
        vm.assume(token != address(c));
        // Ensure token is not already added
        vm.assume(c.rewardPeriodFinish(token) == 0);

        // Capture block.timestamp before addReward
        uint256 tsBefore = block.timestamp;
        c.addReward(token);

        // The rule: rewardPeriodFinish(token) == block.timestamp at the time of addReward
        assertTrue(c.rewardPeriodFinish(token) == uint40(tsBefore));
    }
}

